+// RFC 4180 style: quoted fields may hold commas, newlines and "" escapes.
+function parseCsv(text) {
+  const rows = [];
+  let row = [];
+  let field = "";
+  let quoted = false;
+  for (let i = 0; i < text.length; i++) {
+    const c = text[i];
+    if (quoted) {
+      if (c === '"' && text[i + 1] === '"') {
+        field += '"';
+        i++;
+      } else if (c === '"') quoted = false;
+      else field += c;
+    } else if (c === '"') quoted = true;
+    else if (c === ",") {
+      row.push(field);
+      field = "";
+    } else if (c === "\n" || c === "\r") {
+      if (c === "\r" && text[i + 1] === "\n") i++;
+      row.push(field);
+      rows.push(row);
+      row = [];
+      field = "";
+    } else field += c;
+  }
+  if (field !== "" || row.length) {
+    row.push(field);
+    rows.push(row);
+  }
+  return rows.filter((r) => r.length > 1 || r[0] !== "");
+}
+
+async function readStock() {
+  const [header, ...rows] = parseCsv(await readFile(STOCK_CSV, "utf8"));
+  return rows.map((cells) => {
+    const r = Object.fromEntries(header.map((h, i) => [h, cells[i] ?? ""]));
+    return {
+      sku: r.sku,
+      name: r.name,
+      qty: Number(r.qty),
+      unit: r.unit === "" ? null : r.unit,
+      shelf: r.shelf,
+    };
+  });
+}

